  s32 shiftY;
  s32 shiftX;
  y = valueB;
  x = valueA;
  totalBits = 0x30;
  if ((x == 0) || (y == 0))
  {
    return 0;
  }
  shiftX = 0;
  shiftY = 0;
  maskX = 0x80000000;
  if (x >= 0)
  {
    do
    {
      shiftX += 1;
      maskX = maskX >> 1;
    }
    while (!(maskX & x));
  }
  maskY = 0x80000000;
  if (y >= 0)
  {
    do
    {
      shiftY += 1;
      maskY = maskY >> 1;
    }
    while (!(maskY & y));
  }
  shift = (totalBits - shiftY) - shiftX;
  if (shift > 0xF)
  {
    do
