    s16 stat2D0[3];  /* 0x2D0 */
    s16 stat2D6;     /* 0x2D6 */
    u8 pad2D8[0x24];
    s16 level;       /* 0x2FC */
    u32 exp;         /* 0x300 */
    u8 pad304[8];
    u8 items[20];    /* 0x30C: 2x10 item grid, 0 = empty slot */
