    vu32 *dma;
    s16 *levelPtr;
    s32 *expPtr;
    u8 *stateData;
    u8 *stateIndex;
    u32 *callbackPtr;
    s32 completion;
    s32 rooms;
    s32 expToNext;
    u32 timePacked;
    u32 hours;
    u32 minutes;
    u32 seconds;
    u32 rowIdx;
    u32 entry;
    u32 rowBase;
    u32 col;
    u32 nextRow;
    u32 zero;
    u32 byteOffset;
    s32 stateId;
    u16 *itemTiles;
    u16 *tilePtr;

