    drawDecimal(expToNext, 0x511C, (s16 *)0x06006AB8);
    {
        s16 *p = (s16 *)((u8 *)g + 0x2C8);
        drawDecimal(p[1], 0x511C, (s16 *)0x06006978);
    }
    {
