    s32 count;
    s32 remaining;
    u16 base;
    s32 isFirst;

    remaining = number;
    count = digitCount;
    cursor = dst;
    base = digitBase;
    isFirst = 0;
    while (count != 0)
    {
        s32 digit;
        digit = moduloInt(remaining, 10);
        remaining = divideInt(remaining, 10);
        if (isFirst == 0 || remaining != 0 || digit != 0)
            *cursor = base + digit;
        else
            *cursor = digit;
        cursor--;
        count--;
        isFirst = 1;
    }
}

