    u8 _1E[4];
    s16 animSlot;    /* 0x22: index returned by findKindIndex */
    void *cleanup;   /* 0x24 */
    struct FixedEffectSpriteLayer *layer; /* 0x28 */
    u8 _2C[0xC];
};

